package pgosc

// What CREATE TABLE ... (LIKE ... INCLUDING ALL) doesn't copy and the swap
// has to carry over to the new table: owner, grants (table and column), row
// level security and policies, replica identity, publications, table
// comment, per-column statistics targets and options. And the index and
// constraint names: LIKE names them after the shadow table.
//
// The statements are generated by the server (format(), quote_ident()), the
// same queries as in the Rust port.

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// columnPlaceholder is replaced by the (renamed) column of the new table in
// per-column statements.
const columnPlaceholder = "__PGOSC_COLUMN__"

// Table level statements in the order they must run ('{target}' = the table
// to apply them to, {source} = the source table). The owner goes last: after
// it we may no longer be the owner (still fine as superuser / member).
const tablePropertiesSQL = `
SELECT stmt FROM (
  SELECT 1 AS ord, format('COMMENT ON TABLE %s IS %L', '{target}', d) AS stmt
    FROM obj_description({source}::regclass, 'pg_class') d WHERE d IS NOT NULL
  UNION ALL
  SELECT 2, format('ALTER TABLE %1$s ENABLE ROW LEVEL SECURITY', '{target}')
    FROM pg_class WHERE oid = {source}::regclass AND relrowsecurity
  UNION ALL
  SELECT 2, format('ALTER TABLE %1$s FORCE ROW LEVEL SECURITY', '{target}')
    FROM pg_class WHERE oid = {source}::regclass AND relforcerowsecurity
  UNION ALL
  SELECT 3, format('CREATE POLICY %2$I ON %1$s AS %3$s FOR %4$s TO %5$s%6$s%7$s', '{target}', p.polname,
           CASE WHEN p.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END,
           CASE p.polcmd WHEN 'r' THEN 'SELECT' WHEN 'a' THEN 'INSERT' WHEN 'w' THEN 'UPDATE' WHEN 'd' THEN 'DELETE' ELSE 'ALL' END,
           (SELECT string_agg(CASE WHEN r = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r)) END, ', ') FROM unnest(p.polroles) r),
           ' USING (' || pg_get_expr(p.polqual, p.polrelid) || ')',
           ' WITH CHECK (' || pg_get_expr(p.polwithcheck, p.polrelid) || ')')
    FROM pg_policy p WHERE p.polrelid = {source}::regclass
  UNION ALL
  SELECT 4, format('GRANT %2$s ON %1$s TO %3$s%4$s', '{target}', x.privilege_type,
           CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(x.grantee)) END,
           CASE WHEN x.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END)
    FROM pg_class c, aclexplode(c.relacl) x WHERE c.oid = {source}::regclass AND x.grantee <> c.relowner
  UNION ALL
  SELECT 5, format('ALTER TABLE %1$s REPLICA IDENTITY %2$s', '{target}', CASE relreplident WHEN 'f' THEN 'FULL' ELSE 'NOTHING' END)
    FROM pg_class WHERE oid = {source}::regclass AND relreplident IN ('f', 'n')
  UNION ALL
  SELECT 9, format('ALTER TABLE %1$s OWNER TO %2$I', '{target}', pg_get_userbyid(relowner))
    FROM pg_class WHERE oid = {source}::regclass
) s ORDER BY ord
`

const columnPropertiesSQL = `
SELECT a.attname AS col, s.stmt
FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid,
LATERAL (
  SELECT format('ALTER TABLE %s ALTER COLUMN __PGOSC_COLUMN__ SET STATISTICS %s', '{target}', a.attstattarget)
    WHERE a.attstattarget IS NOT NULL AND a.attstattarget >= 0
  UNION ALL
  SELECT format('ALTER TABLE %s ALTER COLUMN __PGOSC_COLUMN__ SET (%s)', '{target}', array_to_string(a.attoptions, ', '))
    WHERE a.attoptions IS NOT NULL
  UNION ALL
  SELECT format('GRANT %s (__PGOSC_COLUMN__) ON %s TO %s%s', x.privilege_type, '{target}',
           CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(x.grantee)) END,
           CASE WHEN x.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END)
    FROM aclexplode(a.attacl) x WHERE x.grantee <> c.relowner
) s(stmt)
WHERE a.attrelid = {source}::regclass AND a.attnum > 0 AND NOT a.attisdropped
ORDER BY a.attnum
`

const publicationsSQL15 = `
SELECT p.pubname,
       format('ALTER PUBLICATION %I ADD TABLE %s%s%s', p.pubname, '{target}',
         CASE WHEN r.prattrs IS NOT NULL THEN ' (' || (SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum)
           FROM pg_attribute a WHERE a.attrelid = r.prrelid AND a.attnum = ANY (r.prattrs)) || ')' ELSE '' END,
         CASE WHEN r.prqual IS NOT NULL THEN ' WHERE (' || pg_get_expr(r.prqual, r.prrelid) || ')' ELSE '' END) AS stmt
FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
WHERE r.prrelid = {source}::regclass ORDER BY 1
`

const publicationsSQL = `
SELECT p.pubname, format('ALTER PUBLICATION %I ADD TABLE %s', p.pubname, '{target}') AS stmt
FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
WHERE r.prrelid = {source}::regclass ORDER BY 1
`

const indexesSQL = `
SELECT ic.relname AS name, c.conname, c.contype, i.indisreplident,
       (SELECT json_agg(coalesce(a.attname, '') ORDER BY k.ord)
          FROM unnest(i.indkey::int2[]) WITH ORDINALITY k(attnum, ord)
          LEFT JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum) AS cols,
       concat_ws('|', am.amname, i.indisunique, i.indisprimary, i.indnkeyatts, i.indclass::text, i.indoption::text,
                 i.indcollation::text, pg_get_expr(i.indexprs, i.indrelid), pg_get_expr(i.indpred, i.indrelid),
                 array_to_string(ic.reloptions, ',')) AS rest
FROM pg_index i
JOIN pg_class ic ON ic.oid = i.indexrelid
JOIN pg_am am ON am.oid = ic.relam
LEFT JOIN pg_constraint c ON c.conindid = i.indexrelid AND c.conrelid = i.indrelid AND c.contype IN ('p', 'u', 'x')
WHERE i.indrelid = {table}::regclass
ORDER BY i.indexrelid
`

type indexInfo struct {
	name      string
	conname   *string
	replident bool
	key       string
}

type indexPair struct{ source, shadow indexInfo }

// carry holds the statements captured before the swap renames the tables.
type carry struct {
	// run on the new table after the renames, owner last
	statements []string
	// the old table leaves its publications
	oldTableStatements []string
	// renames giving the new table's indexes the original names, replica identity
	nameStatements []string
	warnings       []string
}

func truncateIdent(s string, max int) string {
	if len(s) <= max {
		return s
	}
	end := max
	for end > 0 && (s[end]&0xC0) == 0x80 {
		end--
	}
	return s[:end]
}

func (c *Ctx) sourceRegclass() string { return QuoteLiteral(c.qualified(c.opts.TableName)) }

func (c *Ctx) fill(sql, target, table string) string {
	if table == "" {
		table = c.opts.TableName
	}
	return strings.NewReplacer(
		"{source}", c.sourceRegclass(),
		"'{target}'", QuoteLiteral(target),
		"{table}", QuoteLiteral(c.qualified(table)),
	).Replace(sql)
}

// newColumnName returns the column of the new table for a column of the
// source table, false if the ALTER drops it.
func (c *Ctx) newColumnName(col string) (string, bool) {
	if contains(c.droppedColumns, col) {
		return "", false
	}
	for _, r := range c.renamedColumns {
		if r.Old == col {
			return r.New, true
		}
	}
	return col, true
}

func stmts(rows []Row, col string) []string {
	out := make([]string, 0, len(rows))
	for _, r := range rows {
		if v, ok := r.Get(col); ok {
			out = append(out, v)
		}
	}
	return out
}

// propertyStatements: owner, grants, RLS, policies, replica identity (FULL /
// NOTHING), comment, column statistics/options/grants, publications for
// target, as the source table has them right now.
func (c *Ctx) propertyStatements(target string, reuse bool) ([]string, error) {
	rows, err := c.db.Run(c.fill(tablePropertiesSQL, target, ""), reuse)
	if err != nil {
		return nil, err
	}
	var out, owner []string
	for _, s := range stmts(rows, "stmt") {
		if strings.Contains(s, " OWNER TO ") {
			owner = append(owner, s)
		} else {
			out = append(out, s)
		}
	}
	rows, err = c.db.Run(c.fill(columnPropertiesSQL, target, ""), reuse)
	if err != nil {
		return nil, err
	}
	for _, r := range rows {
		col, ok1 := r.Get("col")
		stmt, ok2 := r.Get("stmt")
		if !ok1 || !ok2 {
			continue
		}
		if newCol, ok := c.newColumnName(col); ok {
			out = append(out, strings.ReplaceAll(stmt, columnPlaceholder, QuoteIdent(newCol)))
		}
	}
	pubSQL := publicationsSQL
	if c.serverVersion >= 150000 {
		pubSQL = publicationsSQL15
	}
	rows, err = c.db.Run(c.fill(pubSQL, target, ""), reuse)
	if err != nil {
		return nil, err
	}
	out = append(out, stmts(rows, "stmt")...)
	return append(out, owner...), nil
}

func (c *Ctx) indexesOf(table string, mapColumns, reuse bool) ([]indexInfo, error) {
	rows, err := c.db.Run(c.fill(indexesSQL, "", table), reuse)
	if err != nil {
		return nil, err
	}
	out := make([]indexInfo, 0, len(rows))
	for _, r := range rows {
		var cols []string
		_ = json.Unmarshal([]byte(r.Val("cols")), &cols)
		if mapColumns {
			for i, col := range cols {
				if col == "" {
					continue
				}
				if n, ok := c.newColumnName(col); ok {
					cols[i] = n
				} else {
					cols[i] = col + "#dropped"
				}
			}
		}
		if cols == nil {
			cols = []string{}
		}
		key, _ := json.Marshal(cols)
		out = append(out, indexInfo{
			name:      r.Val("name"),
			conname:   r.Ptr("conname"),
			replident: r.Val("indisreplident") == "t",
			key:       string(key) + "|" + r.Val("rest"),
		})
	}
	return out, nil
}

// indexPairs pairs the source table's indexes with the shadow table's ones by
// definition. Unpaired ones keep their names (with a warning).
func (c *Ctx) indexPairs(reuse bool) ([]indexPair, []string, error) {
	source, err := c.indexesOf(c.opts.TableName, true, reuse)
	if err != nil {
		return nil, nil, err
	}
	candidates, err := c.indexesOf(c.shadowTable, false, reuse)
	if err != nil {
		return nil, nil, err
	}
	var pairs []indexPair
	var warnings []string
	for _, s := range source {
		found := -1
		for i, cand := range candidates {
			if cand.key == s.key {
				found = i
				break
			}
		}
		if found < 0 {
			warnings = append(warnings, fmt.Sprintf("index %s has no counterpart with the same definition on the new table, its name isn't carried over", s.name))
			continue
		}
		pairs = append(pairs, indexPair{s, candidates[found]})
		candidates = append(candidates[:found], candidates[found+1:]...)
	}
	return pairs, warnings, nil
}

// captureCarry collects everything the swap carries over, inside the swap
// transaction before the renames (the source is still TableName).
func (c *Ctx) captureCarry() (*carry, error) {
	t := c.opts.TableName
	props, err := c.propertyStatements(t, true)
	if err != nil {
		return nil, err
	}
	cr := &carry{statements: props}
	rows, err := c.db.Run(c.fill(publicationsSQL, "", ""), true)
	if err != nil {
		return nil, err
	}
	old := c.qualified(c.oldPrimaryTable)
	for _, pub := range stmts(rows, "pubname") {
		cr.oldTableStatements = append(cr.oldTableStatements, fmt.Sprintf("ALTER PUBLICATION %s DROP TABLE %s;", QuoteIdent(pub), old))
	}
	pairs, warnings, err := c.indexPairs(true)
	if err != nil {
		return nil, err
	}
	cr.warnings = warnings
	schema := QuoteIdent(c.opts.Schema)
	var first, second []string
	for n, p := range pairs {
		if p.source.name == p.shadow.name {
			continue
		}
		// the old table's index first moves out of the way
		tmp := fmt.Sprintf("%s_pgosc_op_%d", truncateIdent(p.source.name, 40), n)
		if p.source.conname != nil && p.shadow.conname != nil {
			first = append(first, fmt.Sprintf("ALTER TABLE %s RENAME CONSTRAINT %s TO %s;", old, QuoteIdent(*p.source.conname), QuoteIdent(tmp)))
			second = append(second, fmt.Sprintf("ALTER TABLE %s.%s RENAME CONSTRAINT %s TO %s;", schema, t, QuoteIdent(*p.shadow.conname), QuoteIdent(*p.source.conname)))
		} else {
			first = append(first, fmt.Sprintf("ALTER INDEX %s.%s RENAME TO %s;", schema, QuoteIdent(p.source.name), QuoteIdent(tmp)))
			second = append(second, fmt.Sprintf("ALTER INDEX %s.%s RENAME TO %s;", schema, QuoteIdent(p.shadow.name), QuoteIdent(p.source.name)))
		}
	}
	cr.nameStatements = append(first, second...)
	replident := false
	for _, p := range pairs {
		if p.source.replident {
			cr.nameStatements = append(cr.nameStatements, fmt.Sprintf("ALTER TABLE %s.%s REPLICA IDENTITY USING INDEX %s;", schema, t, QuoteIdent(p.source.name)))
			replident = true
			break
		}
	}
	if !replident {
		v, err := c.db.FirstValue(fmt.Sprintf("SELECT indexrelid::regclass::text FROM pg_index WHERE indrelid = %s::regclass AND indisreplident;", c.sourceRegclass()), true)
		if err != nil {
			return nil, err
		}
		if v != nil {
			cr.warnings = append(cr.warnings, "the replica identity index has no counterpart on the new table, replica identity stays DEFAULT")
		}
	}
	return cr, nil
}

// checkCarry runs the property statements against the shadow table in a
// transaction and rolls it back, before the sync starts: a missing privilege
// or a policy over a dropped column fails now and not at every swap attempt.
// Logs indexes whose names can't be carried over.
func (c *Ctx) checkCarry() error {
	err := func() error {
		props, err := c.propertyStatements(c.shadowTable, true)
		if err != nil {
			return err
		}
		for _, s := range props {
			if _, err := c.db.Run(s, true); err != nil {
				return fmt.Errorf("The new table can't get a property of the old one (%s): %w", s, err)
			}
		}
		_, warnings, err := c.indexPairs(true)
		for _, w := range warnings {
			Warn(w)
		}
		return err
	}()
	_, _ = c.db.Run("ROLLBACK;", false)
	return err
}

// preflight: checks done before anything is created.
func (c *Ctx) preflight() error {
	rows, err := c.db.Run(fmt.Sprintf(`SELECT c.relkind, c.relispartition, to_regclass(%s) IS NOT NULL AS old_exists,
                        pg_has_role(c.relowner, 'MEMBER') AS can_own, pg_get_userbyid(c.relowner) AS owner
                 FROM pg_class c WHERE c.oid = %s::regclass;`, QuoteLiteral(c.qualified(c.oldPrimaryTable)), c.sourceRegclass()), false)
	if err != nil {
		return err
	}
	if len(rows) == 0 {
		return fmt.Errorf("Table %s not found", c.opts.TableName)
	}
	r := rows[0]
	if r.Val("relkind") == "p" || r.Val("relispartition") == "t" {
		return errors.New("Partitioned tables and partitions are not supported (the shadow table would be a plain table)")
	}
	if r.Val("old_exists") == "t" {
		return fmt.Errorf("%s already exists (left by a previous run without --drop): drop or rename it first, the swap renames the table to that name", c.oldPrimaryTable)
	}
	if r.Val("can_own") != "t" {
		return fmt.Errorf("The new table must get the owner of the old one (%s): run as a superuser or a member of that role", r.Val("owner"))
	}
	rows, err = c.db.Run(fmt.Sprintf(`SELECT p.pubname FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
             WHERE r.prrelid = %s::regclass AND NOT pg_has_role(p.pubowner, 'MEMBER');`, c.sourceRegclass()), false)
	if err != nil {
		return err
	}
	if foreign := stmts(rows, "pubname"); len(foreign) > 0 {
		return fmt.Errorf("The table is in publications %s owned by another role: run as a superuser or their owner, the new table has to join them", strings.Join(foreign, ", "))
	}
	return nil
}
